    (7, 9, 'Day 14', 'Session 7', 'Nguyên tắc', 'Philosophy / principle', 'Công ty này hoạt động dựa trên nguyên tắc minh bạch, luôn đặt lợi ích của khách hàng lên hàng đầu.', 'This company operates on the principle of transparency, always putting the customer''s interests first.', 15, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 15, 'Estimated TC × LC × TL', 'CVR', '{"tc":15,"lc":1.5,"tl":1.5,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"c398a81fc19d3e00","unit_ohm":15,"tc":15,"lc":1.5,"tl":1.5,"audio_text_vi":"Number 09. Công ty này hoạt động dựa trên nguyên tắc minh bạch, luôn đặt lợi ích của khách hàng lên hàng đầu.","audio_text_en":"Number 09. This company operates on the principle of transparency, always putting the customer''s interests first.","expected_cpd_value":225}'::jsonb),
    (7, 10, 'Day 14', 'Session 7', 'Cải thiện', 'Work on / improve', 'Để cải thiện kỹ năng giao tiếp, bạn nên luyện tập nói trước gương và ghi âm để tự đánh giá.', 'To improve your communication skills, you should practice speaking in front of a mirror and record yourself for self-evaluation.', 15, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 15, 'Estimated TC × LC × TL', 'CVR', '{"tc":15,"lc":1.5,"tl":1.5,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"242f31565ac19589","unit_ohm":15,"tc":15,"lc":1.5,"tl":1.5,"audio_text_vi":"Number 10. Để cải thiện kỹ năng giao tiếp, bạn nên luyện tập nói trước gương và ghi âm để tự đánh giá.","audio_text_en":"Number 10. To improve your communication skills, you should practice speaking in front of a mirror and record yourself for self-evaluation.","expected_cpd_value":225}'::jsonb),
    (8, 1, 'Day 15', 'Session 8', 'Ngấn mỡ bụng', 'Love handles', 'Nhiều nhân viên văn phòng vật lộn với ngấn mỡ bụng vì ngồi nhiều giờ mỗi ngày, hiếm khi vận động và thường ăn đồ ngọt.', 'Many office workers struggle with love handles because they sit for long hours every day and rarely exercise, even though their diets are full of sugar and fat.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"ca0a8c5349dc9535","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 01. Nhiều nhân viên văn phòng vật lộn với ngấn mỡ bụng vì ngồi nhiều giờ mỗi ngày, hiếm khi vận động và thường ăn đồ ngọt.","audio_text_en":"Number 01. Many office workers struggle with love handles because they sit for long hours every day and rarely exercise, even though their diets are full of sugar and fat.","expected_cpd_value":289}'::jsonb),
    (8, 2, 'Day 15', 'Session 8', 'Không uống rượu bia (adj)', 'Teetotal', 'Mặc dù thường đi tiệc với đồng nghiệp, anh ấy vẫn không uống rượu bia, và bác sĩ nói thói quen này giúp tim mạch khỏe hơn nhiều.', 'Even though he often joins social parties with colleagues, he remains teetotal, and his doctor says this habit has greatly improved his overall heart health.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"4d97f0d36142391e","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 02. Mặc dù thường đi tiệc với đồng nghiệp, anh ấy vẫn không uống rượu bia, và bác sĩ nói thói quen này giúp tim mạch khỏe hơn nhiều.","audio_text_en":"Number 02. Even though he often joins social parties with colleagues, he remains teetotal, and his doctor says this habit has greatly improved his overall heart health.","expected_cpd_value":289}'::jsonb),
    (8, 3, 'Day 15', 'Session 8', 'Trào ngược dạ dày', 'Acid reflux', 'Trào ngược dạ dày phổ biến ở những ai làm việc căng thẳng, đặc biệt khi họ ăn không đúng giờ hoặc nằm ngay sau bữa ăn.', 'Acid reflux is very common among people who work under high stress, especially when they eat at irregular times or lie down right after their meals.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"7c2068d4b76895e7","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 03. Trào ngược dạ dày phổ biến ở những ai làm việc căng thẳng, đặc biệt khi họ ăn không đúng giờ hoặc nằm ngay sau bữa ăn.","audio_text_en":"Number 03. Acid reflux is very common among people who work under high stress, especially when they eat at irregular times or lie down right after their meals.","expected_cpd_value":289}'::jsonb),
    (8, 4, 'Day 15', 'Session 8', 'Ợ nóng', 'Heartburn', 'Ợ nóng thường xuất hiện sau khi ăn đồ cay hoặc nhiều dầu mỡ, và nếu cảm giác này kéo dài nhiều tuần, bạn nên đi khám.', 'Heartburn often appears after eating spicy or greasy food, and if this burning feeling lasts for weeks, you should go see a doctor for a checkup.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"4e4dbeb94ab88e58","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 04. Ợ nóng thường xuất hiện sau khi ăn đồ cay hoặc nhiều dầu mỡ, và nếu cảm giác này kéo dài nhiều tuần, bạn nên đi khám.","audio_text_en":"Number 04. Heartburn often appears after eating spicy or greasy food, and if this burning feeling lasts for weeks, you should go see a doctor for a checkup.","expected_cpd_value":289}'::jsonb),
    (8, 5, 'Day 15', 'Session 8', 'Đừng ăn khuya nữa', 'Stop eating at night / before bed', 'Chuyên gia dinh dưỡng khuyên đừng ăn khuya nữa nếu muốn giảm cân, vì ăn muộn khiến cơ thể tích mỡ thừa và ngủ kém hơn.', 'Nutrition experts say you should stop eating at night if you want to lose weight, because late meals make the body store extra fat and ruin your sleep.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"41bdd2fce4a0354a","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 05. Chuyên gia dinh dưỡng khuyên đừng ăn khuya nữa nếu muốn giảm cân, vì ăn muộn khiến cơ thể tích mỡ thừa và ngủ kém hơn.","audio_text_en":"Number 05. Nutrition experts say you should stop eating at night if you want to lose weight, because late meals make the body store extra fat and ruin your sleep.","expected_cpd_value":289}'::jsonb),
    (8, 6, 'Day 15', 'Session 8', 'Đường huyết', 'Blood sugar', 'Giữ đường huyết ổn định đóng vai trò quan trọng trong phòng ngừa tiểu đường, đặc biệt với những ai có tiền sử gia đình hoặc thừa cân.', 'Keeping blood sugar levels stable plays a key role in preventing diabetes, especially for those with a family history of the disease or who are overweight.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"880a6858aacdbfee","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 06. Giữ đường huyết ổn định đóng vai trò quan trọng trong phòng ngừa tiểu đường, đặc biệt với những ai có tiền sử gia đình hoặc thừa cân.","audio_text_en":"Number 06. Keeping blood sugar levels stable plays a key role in preventing diabetes, especially for those with a family history of the disease or who are overweight.","expected_cpd_value":289}'::jsonb),
    (8, 7, 'Day 15', 'Session 8', 'Ngộ độc thực phẩm', 'Food poisoning', 'Ngộ độc thực phẩm xảy ra khi bạn ăn đồ ôi thiu, nấu chưa kỹ hoặc bảo quản kém, gây buồn nôn, tiêu chảy và sốt nhẹ.', 'Food poisoning can happen when you eat spoiled, undercooked, or badly stored food, causing nausea, diarrhea, and a mild fever that lasts for two or three days.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"523faad064b61a0f","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 07. Ngộ độc thực phẩm xảy ra khi bạn ăn đồ ôi thiu, nấu chưa kỹ hoặc bảo quản kém, gây buồn nôn, tiêu chảy và sốt nhẹ.","audio_text_en":"Number 07. Food poisoning can happen when you eat spoiled, undercooked, or badly stored food, causing nausea, diarrhea, and a mild fever that lasts for two or three days.","expected_cpd_value":289}'::jsonb),
    (8, 8, 'Day 15', 'Session 8', 'Sự trao đổi chất', 'Metabolism', 'Trao đổi chất của cơ thể chậm lại khi ta già đi, vì vậy việc duy trì thói quen tập luyện đều đặn ngày càng quan trọng.', 'The body''s metabolism tends to slow down as we get older, which is why keeping a regular exercise routine becomes more and more important each year.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"498090918b0f54f1","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 08. Trao đổi chất của cơ thể chậm lại khi ta già đi, vì vậy việc duy trì thói quen tập luyện đều đặn ngày càng quan trọng.","audio_text_en":"Number 08. The body''s metabolism tends to slow down as we get older, which is why keeping a regular exercise routine becomes more and more important each year.","expected_cpd_value":289}'::jsonb),
    (8, 9, 'Day 15', 'Session 8', 'Đồ ăn vặt', 'Snacks / light meal', 'Ăn quá nhiều đồ ăn vặt chứa đầy muối, đường và chất béo không chỉ gây tăng cân mà còn tăng nguy cơ mắc bệnh mạn tính.', 'Eating too many snacks full of salt, sugar, and fat not only causes weight gain but also raises the risk of dangerous chronic diseases later in life.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"970bc2ab74c5c542","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 09. Ăn quá nhiều đồ ăn vặt chứa đầy muối, đường và chất béo không chỉ gây tăng cân mà còn tăng nguy cơ mắc bệnh mạn tính.","audio_text_en":"Number 09. Eating too many snacks full of salt, sugar, and fat not only causes weight gain but also raises the risk of dangerous chronic diseases later in life.","expected_cpd_value":289}'::jsonb),
    (8, 10, 'Day 15', 'Session 8', 'Ngay sau khi ăn', 'Shortly after the meal', 'Nhiều bạn có thói quen nằm ngay sau khi ăn, nhưng bác sĩ cảnh báo việc này tạo áp lực lên dạ dày và dễ gây trào ngược.', 'Many people have the habit of lying down shortly after the meal, but doctors warn this puts pressure on the stomach and easily causes acid reflux.', 17, 'Unit (Ohm)', 'CCI', 'csv:Unit (Ohm)', 17, 'Estimated TC × LC × TL', 'CVR', '{"tc":17,"lc":1.5,"tl":1.8,"formula":"CVR = Estimated TC × LC × TL"}'::jsonb, '{"source":"Chunks-resource - CVR_new.csv","import_key":"8bf292d7198225ef","unit_ohm":17,"tc":17,"lc":1.5,"tl":1.8,"audio_text_vi":"Number 10. Nhiều bạn có thói quen nằm ngay sau khi ăn, nhưng bác sĩ cảnh báo việc này tạo áp lực lên dạ dày và dễ gây trào ngược.","audio_text_en":"Number 10. Many people have the habit of lying down shortly after the meal, but doctors warn this puts pressure on the stomach and easily causes acid reflux.","expected_cpd_value":289}'::jsonb)
)
insert into public.live_test_items (block_id, item_number, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, cci_value, cci_measure, cci_unit_label, cci_source, cvr_value, cvr_measure, cvr_unit_label, cvr_breakdown, metadata)
select b.id, i.item_number, i.source_day, i.source_stt, i.term_vi, i.term_en, i.prompt_vi, i.prompt_en, i.cci_value, i.cci_measure, i.cci_unit_label, i.cci_source, i.cvr_value, i.cvr_measure, i.cvr_unit_label, i.cvr_breakdown, i.metadata
from item_rows i
join resource r on true
join public.live_test_blocks b on b.resource_id = r.id and b.block_number = i.block_number
on conflict (block_id, item_number) do update set
  source_day = excluded.source_day,
  source_stt = excluded.source_stt,
  term_vi = excluded.term_vi,
  term_en = excluded.term_en,
  prompt_vi = excluded.prompt_vi,
  prompt_en = excluded.prompt_en,
  cci_value = excluded.cci_value,
  cci_measure = excluded.cci_measure,
  cci_unit_label = excluded.cci_unit_label,
  cci_source = excluded.cci_source,
  cvr_value = excluded.cvr_value,
  cvr_measure = excluded.cvr_measure,
  cvr_unit_label = excluded.cvr_unit_label,
  cvr_breakdown = excluded.cvr_breakdown,
  metadata = excluded.metadata;



-- ---------------------------------------------------------------------------
-- Direct V2 Catalog Seed Insertion (bypassing local-only settings check)
-- ---------------------------------------------------------------------------

-- CCI profile/category seed mapping by singleton organization and migrated values.
insert into public.cci_profiles (id, organization_id, name, version_label, status, description, created_by_user_id)
select distinct
  public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || r.organization_id::text),
  r.organization_id,
  'Migrated CSV CCI Profile',
  '1.0.0',
  'draft',
  'Seeded from reviewed one-time Live Test V2 migration.',
  null::uuid
from public.live_test_resources r
where r.organization_id is not null
  and not exists (
    select 1 from public.cci_profiles p
    where p.id = public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || r.organization_id::text)
  );

insert into public.cci_categories (id, profile_id, category_order, label, value, metadata)
select
  public.live_test_v2_deterministic_uuid('cci-category:migrated-csv:' || cci.organization_id::text || ':' || cci.cci_value::text),
  public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || cci.organization_id::text),
  dense_rank() over (partition by cci.organization_id order by cci.cci_value),
  'Migrated CCI ' || cci.cci_value::text,
  cci.cci_value,
  jsonb_build_object('source', 'Chunks-resource - CVR_new.csv')
from (
  select distinct r.organization_id, i.cci_value
  from public.live_test_resources r
  join public.live_test_blocks b on b.resource_id = r.id
  join public.live_test_items i on i.block_id = b.id
  where r.organization_id is not null
    and i.cci_value is not null
) cci
join public.cci_profiles profile
  on profile.id = public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || cci.organization_id::text)
 and profile.status = 'draft'
where not exists (
  select 1 from public.cci_categories existing
  where existing.id = public.live_test_v2_deterministic_uuid('cci-category:migrated-csv:' || cci.organization_id::text || ':' || cci.cci_value::text)
);

insert into public.test_packages (id, organization_id, title, slug, description, created_by_user_id, source_metadata)
select
  public.live_test_v2_deterministic_uuid('live-test-package:' || r.id::text),
  r.organization_id,
  r.title,
  'migrated-' || lower(regexp_replace(r.title, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substr(r.id::text, 1, 8),
  'Migrated from legacy live_test_resources without deleting legacy rows.',
  null::uuid,
  jsonb_build_object('legacyLiveTestResourceId', r.id, 'sourceFilename', 'Chunks-resource - CVR_new.csv')
from public.live_test_resources r
where r.organization_id is not null
  and not exists (
    select 1 from public.test_packages p
    where p.id = public.live_test_v2_deterministic_uuid('live-test-package:' || r.id::text)
  );

insert into public.test_package_versions (id, package_id, version_label, status, source_metadata, created_by_user_id)
select
  public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version),
  public.live_test_v2_deterministic_uuid('live-test-package:' || r.id::text),
  coalesce(nullif(r.version, ''), '1.0.0'),
  'draft',
  jsonb_build_object('legacyLiveTestResourceId', r.id, 'legacyStatus', r.status, 'sourceFilename', 'Chunks-resource - CVR_new.csv'),
  null::uuid
from public.live_test_resources r
where not exists (
  select 1 from public.test_package_versions v
  where v.id = public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version)
);

insert into public.test_sections (id, package_version_id, section_order, title, target_cvr_ohm, cci_profile_id, cci_category_id, cci_snapshot, intro_text_vi, intro_text_en, metadata)
select
  public.live_test_v2_deterministic_uuid('live-test-section:' || b.id::text),
  public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version),
  b.block_number,
  b.title,
  min(i.unit_ohm),
  public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || r.organization_id::text),
  public.live_test_v2_deterministic_uuid('cci-category:migrated-csv:' || r.organization_id::text || ':' || min(i.cci_value)::text),
  jsonb_build_object('label', 'Migrated CCI ' || min(i.cci_value)::text, 'value', min(i.cci_value), 'source', 'Chunks-resource - CVR_new.csv'),
  b.intro_text_vi,
  b.intro_text_en,
  jsonb_build_object('legacyLiveTestBlockId', b.id)
from public.live_test_resources r
join public.live_test_blocks b on b.resource_id = r.id
join public.live_test_items i on i.block_id = b.id
join public.test_package_versions v
  on v.id = public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version)
 and v.status = 'draft'
group by r.id, r.version, r.organization_id, b.id, b.block_number, b.title, b.intro_text_vi, b.intro_text_en
  having not exists (
    select 1 from public.test_sections ts
    where ts.id = public.live_test_v2_deterministic_uuid('live-test-section:' || b.id::text)
  );

insert into public.section_measurement_snapshots (id, test_section_id, package_version_id, target_cvr_ohm, cci_profile_id, cci_category_id, cci_category_label, cci_value, snapshot_metadata, created_by_user_id)
select
  public.live_test_v2_deterministic_uuid('section-measurement-snapshot:' || b.id::text),
  public.live_test_v2_deterministic_uuid('live-test-section:' || b.id::text),
  public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version),
  min(i.unit_ohm),
  public.live_test_v2_deterministic_uuid('cci-profile:migrated-csv:' || r.organization_id::text),
  public.live_test_v2_deterministic_uuid('cci-category:migrated-csv:' || r.organization_id::text || ':' || min(i.cci_value)::text),
  'Migrated CCI ' || min(i.cci_value)::text,
  min(i.cci_value),
  jsonb_build_object('legacyLiveTestBlockId', b.id, 'sourceFilename', 'Chunks-resource - CVR_new.csv'),
  null::uuid
from public.live_test_resources r
join public.live_test_blocks b on b.resource_id = r.id
join public.live_test_items i on i.block_id = b.id
join public.test_package_versions v
  on v.id = public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version)
 and v.status = 'draft'
group by r.id, r.version, r.organization_id, b.id
  having not exists (
    select 1 from public.section_measurement_snapshots sms
    where sms.id = public.live_test_v2_deterministic_uuid('section-measurement-snapshot:' || b.id::text)
  );

insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, tc, lc, tl, cvr_breakdown, source_metadata)
select
  public.live_test_v2_deterministic_uuid('live-test-item-v2:' || i.id::text),
  public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version),
  public.live_test_v2_deterministic_uuid('live-test-section:' || b.id::text),
  i.item_number,
  i.source_day,
  i.source_stt,
  i.term_vi,
  i.term_en,
  i.prompt_vi,
  i.prompt_en,
  coalesce(i.tc, nullif(i.cvr_breakdown->>'tc', '')::numeric),
  coalesce(i.lc, nullif(i.cvr_breakdown->>'lc', '')::numeric),
  coalesce(i.tl, nullif(i.cvr_breakdown->>'tl', '')::numeric),
  jsonb_build_object('legacyCvrValue', i.cvr_value, 'legacyCvrBreakdown', i.cvr_breakdown),
  jsonb_build_object('legacyLiveTestItemId', i.id, 'sourceFilename', 'Chunks-resource - CVR_new.csv')
from public.live_test_resources r
join public.live_test_blocks b on b.resource_id = r.id
join public.live_test_items i on i.block_id = b.id
join public.test_package_versions v
  on v.id = public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version)
 and v.status = 'draft'
where not exists (
  select 1 from public.test_items ti
  where ti.id = public.live_test_v2_deterministic_uuid('live-test-item-v2:' || i.id::text)
);

insert into public.live_test_v2_item_mappings (legacy_live_test_resource_id, legacy_live_test_block_id, legacy_live_test_item_id, target_test_package_id, target_package_version_id, target_test_section_id, target_test_item_id, legacy_external_ref, v2_external_ref, source_row_checksum, source_metadata)
select
  r.id,
  b.id,
  i.id,
  public.live_test_v2_deterministic_uuid('live-test-package:' || r.id::text),
  public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version),
  public.live_test_v2_deterministic_uuid('live-test-section:' || b.id::text),
  public.live_test_v2_deterministic_uuid('live-test-item-v2:' || i.id::text),
  'live-test-item:' || i.id::text,
  'live-test-item:' || public.live_test_v2_deterministic_uuid('live-test-item-v2:' || i.id::text)::text || ':v' || public.live_test_v2_deterministic_uuid('live-test-package-version:' || r.id::text || ':' || r.version)::text,
  public.live_test_v2_source_row_checksum(i),
  jsonb_build_object('sourceFilename', 'Chunks-resource - CVR_new.csv')
from public.live_test_resources r
join public.live_test_blocks b on b.resource_id = r.id
join public.live_test_items i on i.block_id = b.id
where exists (
  select 1 from public.test_items ti
  where ti.id = public.live_test_v2_deterministic_uuid('live-test-item-v2:' || i.id::text)
)
on conflict (legacy_live_test_item_id) do nothing;

update public.cci_profiles profile
set status = 'active'
where profile.name = 'Migrated CSV CCI Profile'
  and profile.status = 'draft';

update public.test_package_versions v
set status = 'published',
    snapshot_hash = 'sha256:' || encode(extensions.digest(convert_to(v.id::text || ':' || v.source_metadata::text, 'UTF8'), 'sha256'), 'hex')
where v.status = 'draft'
  and exists (
    select 1 from public.test_items ti where ti.package_version_id = v.id
  );
